157	// Runner invocations inside one Bash command. Requires `node` and the `.mjs` on the
158	// same shell word run — so `grep -i check_the_world` never counts — and the
159	// separator class stops one match from swallowing a second runner on the same line.
160	const INVOKE_RE = /\bnode\b[^\n;|&]*?\bcheck_the_(work|world)\.mjs\b/g;
161	export function checkInvocations(command) {
162	  const counts = { work: 0, world: 0 };
163	  for (const m of String(command ?? '').matchAll(INVOKE_RE)) counts[m[1]] += 1;
164	  return counts;
165	}
