167	// A tool that fetches CI job logs — the one way a CI run reaches a session, and
168	// therefore the one way "the agent was in the loop on this CI run" is observable.
169	// Matched by name shape rather than by one hardcoded tool: the same session can
170	// reach CI through an MCP server, a different server, or a future rename, and all of
171	// them say what they are in their name.
172	const CI_LOG_TOOL_RE = /(job|run|workflow)_logs/i;
173	
174	// The transcript entries that can carry check output, reduced to the text to read
175	// and the source that produced it. Five shapes, all verified against real captures:
176	// the hook's blocking feedback (an `isMeta` user turn), the harness's
177	// `stop_hook_summary` (which repeats that same stderr), the passing hook's
178	// `hook_success` attachment, a Bash tool result, and a fetched CI job log — the last
179	// two paired back to the tool that produced them, so a Read of a file that merely
180	// CONTAINS this vocabulary is never mistaken for a run.
181	//
182	// Two different duplicate problems, so two different identities:
183	//   - the first two shapes are ONE hook execution recorded twice, so hook texts
184	//     dedupe on the `hooklog` stamps they carry — stable across both shapes and
185	//     unique per execution (its own timestamp, to the second);
186	//   - a CI job log can be fetched repeatedly (re-read while iterating), and there is
187	//     no per-fetch identity that says which RUN it was, so CI texts dedupe on the
188	//     check output itself. Two fetches of one job are byte-identical and collapse;
189	//     two real runs differ by their Actions timestamps at least. Two genuinely
190	//     identical runs would collapse too — an under-count, which is the direction
191	//     this whole counter is allowed to be wrong in.
192	// A Bash result needs neither: each tool call is its own run, and the invocation is
193	// counted from the command.
194	export function checkOutputs(entries) {
195	  const toolById = new Map();
196	  for (const entry of entries) {
197	    if (entry?.type !== 'assistant') continue;
198	    for (const block of entry?.message?.content ?? []) {
199	      if (block?.type !== 'tool_use' || typeof block?.name !== 'string') continue;
200	      if (block.name === 'Bash' && typeof block?.input?.command === 'string') {
201	        toolById.set(block.id, { source: 'bash', command: block.input.command });
202	      } else if (CI_LOG_TOOL_RE.test(block.name)) {
203	        toolById.set(block.id, { source: 'ci', command: null });
204	      }
205	    }
206	  }
207	
208	  const out = [];
209	  const seenHooks = new Set();
210	  const seenCi = new Set();
211	  const hook = (text) => {
212	    const key = hookCheckRuns(text).map((r) => r.stamp).join('|');
213	    if (key && seenHooks.has(key)) return;      // the same execution, recorded twice
214	    if (key) seenHooks.add(key);
215	    out.push({ source: 'hook', text, command: null });
216	  };
217	
218	  for (const entry of entries) {
219	    if (entry?.type === 'system' && entry?.subtype === 'stop_hook_summary') {
220	      hook((entry.hookErrors ?? []).join('\n'));
221	    } else if (entry?.type === 'attachment' && entry?.attachment?.hookEvent === 'Stop') {
222	      hook(`${entry.attachment.stderr ?? ''}\n${entry.attachment.stdout ?? ''}`);
223	    } else if (entry?.type === 'user' && entry?.isMeta === true && typeof entry?.message?.content === 'string') {
224	      if (entry.message.content.includes('Stop hook feedback')) hook(entry.message.content);
225	    } else if (entry?.type === 'user' && Array.isArray(entry?.message?.content)) {
226	      for (const block of entry.message.content) {
227	        if (block?.type !== 'tool_result') continue;
228	        const tool = toolById.get(block.tool_use_id);
229	        if (tool === undefined) continue;       // neither a runner nor a CI log — not a run
230	        const text = resultText(entry.toolUseResult, block.content);
231	        if (tool.source === 'ci') {
232	          // The CI log's OWN content is its identity; a fetch that carried no check
233	          // output at all (a green run, a different job) is not a run to dedupe.
234	          const key = checkOutputKey(text);
235	          if (!key || seenCi.has(key)) continue;
236	          seenCi.add(key);
237	        }
238	        out.push({ source: tool.source, text, command: tool.command });
239	      }
240	    }
241	  }
242	  return out;
243	}
