245	// A tool result's text, whichever shape the tool reports in: Bash reports
246	// `{ stdout, stderr }`, an MCP tool reports content blocks the harness also copies
247	// onto the result block. Both are read, so neither tool family needs special-casing
248	// beyond this one function.
249	function resultText(result, blockContent) {
250	  if (typeof result === 'string') return unwrapJson(result);
251	  if (result && (typeof result.stdout === 'string' || typeof result.stderr === 'string')) {
252	    return `${unwrapJson(result.stdout ?? '')}\n${result.stderr ?? ''}`;
253	  }
254	  if (typeof blockContent === 'string') return unwrapJson(blockContent);
255	  if (Array.isArray(blockContent)) {
256	    return unwrapJson(blockContent.map((b) => (typeof b?.text === 'string' ? b.text : '')).join('\n'));
257	  }
258	  return result === undefined || result === null ? '' : unwrapJson(JSON.stringify(result));
259	}
260	
261	// An MCP tool returns its payload as a JSON DOCUMENT inside a text block, so a job
262	// log's newlines arrive escaped and every mark below — all of them line-anchored —
263	// would see one enormous single line and match nothing. Decode by parsing and
264	// joining every string leaf with real newlines: field names never matter, so this
265	// holds for whichever tool or server delivers the log. Text that is not JSON is
266	// returned untouched, which is every Bash stdout.
267	function unwrapJson(text) {
268	  const trimmed = String(text ?? '').trim();
269	  if (!trimmed.startsWith('{') && !trimmed.startsWith('[')) return text;
270	  let parsed;
271	  try { parsed = JSON.parse(trimmed); } catch { return text; }
272	  const strings = [];
273	  const walk = (value) => {
274	    if (typeof value === 'string') strings.push(value);
275	    else if (Array.isArray(value)) value.forEach(walk);
276	    else if (value && typeof value === 'object') Object.values(value).forEach(walk);
277	  };
278	  walk(parsed);
279	  return strings.join('\n');
280	}
281	
282	// The check output a text carries, as one string — the identity of a CI job log for
283	// deduping. Built from the marked lines only, so unrelated log noise around them
284	// (which differs between a tailed fetch and a full one) cannot make one run look
285	// like two.
286	function checkOutputKey(text) {
287	  const marks = [
288	    ...String(text ?? '').matchAll(SUMMARY_RE),
289	    ...String(text ?? '').matchAll(HEADER_RE),
290	  ].map((m) => m[0]);
291	  return marks.length ? marks.join('|') : null;
292	}
293	
294	// An empty per-scope check row. Uniform across scopes so folding is one loop:
295	// `runs` is observed activations, `failures` the subset that reported at least one
296	// blocking finding, `errors` the runs where the runner itself could not launch, and
297	// `blocking`/`advisory` the finding VOLUME summed over those runs (a rule blocking
298	// twice across two runs counts twice — the question is how often the checks caught
299	// something, not how many distinct problems existed).
300	//
301	// `ciRuns`/`ciFailures` are the SUBSET of `runs`/`failures` that came from a CI job
302	// log the session pulled in, carried separately because that source can only see a
303	// run that printed something: a green CI sweep prints nothing and is invisible. A
304	// consumer wanting a rate over runs it can see the whole of subtracts them; one
305	// asking "how often did the checks catch something" adds nothing and uses the total.
306	const emptyScope = () => Object.fromEntries(USAGE_FIELDS.checks.map((f) => [f, 0]));
307	
308	// Count check activations across one capture file's entries.
309	//
310	// Runs are counted from the marks that a PASSING run also leaves — hook completion
311	// lines, and Bash invocations — never from the summary line, which only a run with
312	// findings prints. Where a runner ran without its command naming it (a `make test`
313	// step that wraps it), the summary lines in its output are the floor: hence the
314	// `max` — the two signals are alternative views of the same runs, not additive ones.
315	export function countChecks(entries) {
316	  const checks = {};
317	  const checkFindings = {};
318	  const scope = (name) => (checks[name] ??= emptyScope());
319	  const finding = (rule, severity) => {
320	    (checkFindings[rule] ??= { blocking: 0, advisory: 0 })[severity] += 1;
321	  };
322	
323	  for (const { source, text, command } of checkOutputs(entries)) {
324	    const summaries = checkSummaries(text);
325	
326	    if (source === 'hook') {
327	      // The hook only ever runs the WORK scope, and its completion line is the run.
328	      for (const run of hookCheckRuns(text)) {
329	        const work = scope('work');
330	        work.runs += 1;
331	        if (run.reason === 'runner-error') work.errors += 1;
332	        // A relent prints the reason instead of the findings, so its failure is
333	        // visible here and nowhere else.
334	        if (run.reason === 'loop-guard-relent') work.failures += 1;
335	      }
336	      for (const s of summaries) if (s.blocking > 0) scope(s.scope).failures += 1;
337	    } else if (source === 'ci') {
338	      // A CI log has no invocation to count — the summary lines ARE the runs, and
339	      // only the runs that printed. Recorded in the totals AND in the ci-only
340	      // counters, so the visible-in-full share stays derivable.
341	      for (const name of ['work', 'world']) {
342	        const reported = summaries.filter((s) => s.scope === name);
343	        if (reported.length === 0) continue;
344	        const failed = reported.filter((s) => s.blocking > 0).length;
345	        const row = scope(name);
346	        row.runs += reported.length;
347	        row.ciRuns += reported.length;
348	        row.failures += failed;
349	        row.ciFailures += failed;
350	      }
351	    } else {
352	      const invoked = checkInvocations(command);
353	      for (const name of ['work', 'world']) {
354	        const reported = summaries.filter((s) => s.scope === name);
355	        const runs = Math.max(invoked[name], reported.length);
356	        if (runs === 0) continue;
357	        scope(name).runs += runs;
358	        scope(name).failures += reported.filter((s) => s.blocking > 0).length;
359	      }
360	    }
361	
362	    for (const s of summaries) {
363	      const row = scope(s.scope);
364	      row.blocking += s.blocking;
365	      row.advisory += s.advisory;
366	    }
367	    for (const f of findingHeaders(text)) finding(f.rule, f.severity);
368	  }
369	  return { checks, checkFindings };
