   162	    if (!at) continue;
   163	    const date = String(at).slice(0, 10);
   164	    days[date] = (days[date] ?? 0) + 1;
   165	  }
   166	  // Newest-first and capped at one page: a repo publishing more than 100 releases
   167	  // inside the window would under-report the far end. Stated rather than silently
   168	  // truncated — the caller logs it.
   169	  return { days, truncated: list.length >= 100 };
   170	}
   171	
   172	// The two series above, merged into the per-day field map `foldUsage` takes: a day
   173	// gets a key only from a source that could speak for it.
   174	export function dayFieldsFrom({ commits = null, releases = null, ladder = [] }) {
   175	  const out = {};
   176	  for (const date of ladder) {
   177	    const fields = {};
   178	    if (commits && date >= commits.coveredFrom) {
   179	      const row = commits.days[date] ?? { commits: 0, linesAdded: 0, linesRemoved: 0 };
   180	      Object.assign(fields, row);
   181	    }
   182	    if (releases) fields.releases = releases.days[date] ?? 0;
   183	    if (Object.keys(fields).length) out[date] = fields;
   184	  }
   185	  return out;
   186	}
   187	
   188	// The window's UTC days, oldest first.
   189	export function dayLadder(nowIso, days = DAY_WINDOW_DAYS) {
   190	  const end = new Date(`${nowIso.slice(0, 10)}T00:00:00Z`).getTime();
   191	  return Array.from({ length: days }, (_, i) => new Date(end - (days - 1 - i) * 86400000).toISOString().slice(0, 10));
