   210	  if (found === null) log(`no ${BRANCH} branch — nothing captured yet; folding the run, queue and git sources only`);
   211	
   212	  let config = {};
   213	  try { config = JSON.parse(readFileSync(settingsPath(root), 'utf8')); } catch { /* no declaration */ }
   214	  const mounted = await mountedSkillNames(root, config);
   215	
   216	  const files = (found?.names ?? []).map((name) => ({
   217	    ...parseLogName(name),
   218	    counts: countEntries(parseEntries(git(root, ['show', `${found.tip}:${name}`])), mounted),
   219	  }));
