   307	}
   308	
   309	// Run only when invoked directly (code-work's `node worker.mjs`), never on import.
   310	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
   311	  main().catch((e) => { console.error(`usage-fold failed: ${e.message}`); process.exit(1); });
   312	}
