     1	// The usage fold's THIRD source: what each scheduled occurrence actually came to.
     2	//
     3	// The slot scheduler used to print that per due task into its own Actions log, and the
     4	// fold counted those lines. That writer retired with the slot scheduler (#974) and the
     5	// queue does not print an equivalent — because it does not need to. Every occurrence
     6	// is a work ITEM, and when it converges it closes wearing an `outcome:*` label. The
     7	// record is better than the log line was (it survives Actions retention, it is
     8	// clickable, and it carries the task on its own title) and it is a different read,
     9	// which is what #994 asked for. This module is that read.
    10	//
    11	// APPEND-ONCE past `queueFoldedThrough`, for the same reason the run listing is
    12	// forward-only: this is a paged REST resource where the capture files are local git.
    13	// It is safe to append rather than recompute because a CLOSED item is settled — the
    14	// outcome label is written at convergence and nothing later moves it — so an item is
    15	// counted on the one fold that first sees it closed and never again.
    16	//
    17	// The boundary is `closed_at`, not `updated_at`: the listing is asked for everything
    18	// touched since the mark (a comment on an old item counts as a touch), and only items
    19	// that closed past the mark are counted. Closing happens in real time, so the mark is
    20	// monotone and the filter is exactly-once.
    21	//
    22	// FAIL-SOFT, like every other source here: an unreadable listing costs the queue rows
    23	// this run and leaves the mark where it was.
    24	
    25	// One definition of what a work item is, shared with the queue's own reader — a filed
    26	// `[claudinite-work]` issue OR an adopted marked issue, which keeps the person's title.
    27	import { isQueueItem } from '../../../claudinite-tasks/queue/read.mjs';
    28	import {
    29	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, outcomeOf,
    30	} from '../../../claudinite-tasks/queue/work-item.mjs';
    31	
    32	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
    33	
    34	// How far back the FIRST read looks with no mark yet — the day tier's own width, so
    35	// one fold populates the whole window rather than starting it empty.
    36	export const FIRST_READ_LOOKBACK_DAYS = 30;
    37	
    38	export const lookbackFrom = (nowIso, days = FIRST_READ_LOOKBACK_DAYS) =>
    39	  new Date(new Date(nowIso).getTime() - days * 86400000).toISOString();
    40	
    41	export function makeReader({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
    42	  const headers = {
    43	    accept: 'application/vnd.github+json',
    44	    'x-github-api-version': '2022-11-28',
    45	    'user-agent': 'claudinite-usage-fold',
    46	    ...(token ? { authorization: `Bearer ${token}` } : {}),
    47	  };
    48	  return {
    49	    async json(path) {
    50	      const res = await fetchImpl(`${api}${path}`, { headers });
    51	      if (res.status !== 200) return null;
    52	      try { return await res.json(); } catch { return null; }
    53	    },
    54	  };
    55	}
    56	
    57	// The task an item belongs to. A filed item says so in its title; an ADOPTED marked
    58	// issue keeps the person's own title and says so in the machine block its body carries
    59	// — the same two-step the dashboard's own reader makes, so a request-shaped run is not
    60	// silently counted as belonging to no task.
    61	export function taskOf(issue) {
    62	  const fromTitle = parseWorkItemTitle(issue?.title);
    63	  if (fromTitle) return { pack: fromTitle.pack, task: fromTitle.task };
    64	  const fromBody = taskIdFromPath(parseWorkItemBody(issue?.body).taskPath);
    65	  return fromBody ? { pack: fromBody.pack, task: fromBody.task } : null;
    66	}
    67	
    68	// One closed item → a record, or null when it is not this fold's business.
    69	export function recordFor(issue, since) {
    70	  if (!isQueueItem(issue)) return null;
    71	  const closedAt = issue?.closed_at ?? null;
    72	  if (!closedAt) return null;
    73	  if (since && closedAt <= since) return null;
    74	  const task = taskOf(issue);
    75	  if (!task) return null;
    76	  return { date: closedAt.slice(0, 10), closedAt, ...task, outcome: outcomeOf(issue) ?? 'none' };
    77	}
    78	
    79	// The whole read: `{ records, watermark, error? }`.
    80	export async function readQueueOutcomes({ reader, repo, since, now, maxPages = 5 }) {
    81	  const from = since || lookbackFrom(now);
    82	  const records = [];
    83	  try {
    84	    for (let page = 1; page <= maxPages; page += 1) {
    85	      const path = `/repos/${repo}/issues?state=closed&sort=updated&direction=desc`
    86	        + `&since=${encodeURIComponent(from)}&per_page=100&page=${page}`;
    87	      const batch = await reader.json(path);
    88	      if (!Array.isArray(batch) || batch.length === 0) break;
    89	      for (const issue of batch) {
    90	        if (issue?.pull_request) continue;         // the issues endpoint answers with both
    91	        const rec = recordFor(issue, since);
    92	        if (rec) records.push(rec);
    93	      }
    94	      if (batch.length < 100) break;
    95	    }
    96	  } catch {
    97	    return { records: [], watermark: since, error: 'the closed work items could not be listed' };
    98	  }
    99	  const newest = records.map((r) => r.closedAt).sort().pop() ?? null;
   100	  return { records, watermark: newest ?? since ?? null };
   101	}

