     1	#!/usr/bin/env node
     2	// SessionStart step: state, in one line, WHAT ACTUALLY LOADED this session —
     3	// the active packs, the checks they arm, the token weight of the prose injected,
     4	// the skills mounted, plus whatever facet an active pack contributes about
     5	// itself. Its stdout becomes session context, and it carries the directive that
     6	// makes the session open with the line, so the person in front of it sees the
     7	// load stated back rather than having to trust that it happened.
     8	//
     9	// WHY IT IS NOT THE ORCHESTRATOR'S FOOTER. That footer reports the MACHINERY:
    10	// which steps ran and which crashed. This reports the VOLUME: how much guidance
    11	// is in the window and how much of it is armed as checks. The two answer
    12	// different questions and neither substitutes for the other — a session where
    13	// every step ran and nothing was declared looks identical from the footer alone.
    14	//
    15	// RUNS LAST, after the steps whose work it counts (the skill mount), so it describes
    16	// the session that exists rather than the one about to. The prose it weighs no longer
    17	// arrives through this hook at all — it rides CLAUDE.md since #807 — but the weight is
    18	// still this line's to state, because the cost lands in the same context window and a
    19	// session that cannot see it has no way to notice the corpus growing.
    20	//
    21	// Core names no pack to get a pack-specific facet. A pack that has one states it
    22	// on the FACET CHANNEL — a `CLAUDINITE-FACET:` line from its session-start step,
    23	// collected by the step runner (engine/pack_loader/run-pack-session-start.mjs)
    24	// into the file `CLAUDINITE_SESSION_FACETS` names — and this step appends what it
    25	// finds there. The channel rides the step because the facts worth stating are the
    26	// ones a pack had to COMPUTE: a static count is already in prose the reader has.
    27	//
    28	// Fails soft to silence, and exits 0 always — a non-zero exit makes Claude Code
    29	// DISCARD the orchestrator's whole stdout, including the steps that did work.
    30	import { readFileSync, existsSync } from 'node:fs';
    31	import { join, dirname } from 'node:path';
    32	import { fileURLToPath } from 'node:url';
    33	import { settingsPath } from '../settings-file.mjs';
    34	
    35	// The prose is reported in TOKENS because that is the unit of the cost it
    36	// imposes — a context window, not a disk. The estimate goes through WORDS at the
    37	// standard English ratio of roughly 0.75 words per token: prose is words, and a
    38	// character count is thrown off by exactly what this corpus is full of — code
    39	// fences, paths, punctuation-dense Markdown. Rounded, because a session summary
    40	// is a sense of scale, not an accounting.
    41	const WORDS_PER_TOKEN = 0.75;
    42	const TOKEN_ROUNDING = 500;
    43	const plural = (n, one, many = `${one}s`) => `${n.toLocaleString('en-US')} ${n === 1 ? one : many}`;
    44	
    45	try {
    46	  const loaderDir = dirname(fileURLToPath(import.meta.url)); // <corpus>/engine/pack_loader
    47	  const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
    48	
    49	  let declared = [];
    50	  const configPath = settingsPath(projectRoot);
    51	  if (existsSync(configPath)) {
    52	    const raw = JSON.parse(readFileSync(configPath, 'utf8'));
    53	    if (Array.isArray(raw.packs)) declared = raw.packs;
    54	  }
    55	
    56	  const { loadPacks, isActive, bundledSkillSources } = await import(join(loaderDir, 'pack-registry.mjs'));
    57	  const packs = await loadPacks({ localRoot: projectRoot });
    58	  const active = packs.filter((pack) => isActive(pack, { packs: declared }));
    59	  // Nothing active means this repo runs no Claudinite. Nothing loaded, so there
    60	  // is nothing to state — the same silence the prose injector keeps.
    61	  if (!active.length) process.exit(0);
    62	
    63	  // The prose the injector actually emits: each active pack's own file, resolved
    64	  // off the pack's directory, trimmed the way the injector trims it. The routing
    65	  // table and the directory pointer are the injector's framing rather than a
    66	  // pack's rules, so they are not counted here.
    67	  let proseWords = 0;
    68	  for (const pack of active) {
    69	    if (!pack.prose) continue;
    70	    const prosePath = join(pack.dir, pack.prose);
    71	    if (!existsSync(prosePath)) continue;
    72	    try {
    73	      proseWords += readFileSync(prosePath, 'utf8').trim().split(/\s+/).filter(Boolean).length;
    74	    } catch { /* an unreadable file counts as none */ }
    75	  }
    76	  const tokens = Math.round(proseWords / WORDS_PER_TOKEN / TOKEN_ROUNDING) * TOKEN_ROUNDING;
    77	
    78	  // Checks are the active packs' rules, both scopes — what check_the_world and
    79	  // check_the_work between them will run against this repo.
    80	  const checks = active.reduce((n, pack) => n + (pack.rules?.length ?? 0), 0);
    81	
    82	  const facets = [
    83	    plural(active.length, 'pack'),
    84	    plural(checks, 'check'),
    85	    `${tokens.toLocaleString('en-US')} rule tokens`,
    86	    plural(bundledSkillSources(active).size, 'available skill'),
    87	  ];
    88	
    89	  // Whatever the active packs' steps said about themselves, in the order the
    90	  // runner ran them. Absent file, unreadable file, no channel at all: the engine
    91	  // facets stand on their own.
    92	  const facetsFile = process.env.CLAUDINITE_SESSION_FACETS;
    93	  if (facetsFile && existsSync(facetsFile)) {
    94	    try {
    95	      for (const line of readFileSync(facetsFile, 'utf8').split('\n')) {
    96	        if (line.trim()) facets.push(line.trim());
    97	      }
    98	    } catch { /* one unreadable channel is not the session's problem */ }
    99	  }
   100	
   101	  // The directive comes FIRST and the line it names comes last, quoted by the colon:
   102	  // a reader picking the nearest line then picks the summary. Said the other way round,
   103	  // with the summary above and a "repeat that line" below it, the nearest line is the
   104	  // directive itself — and sessions duly opened their replies by reciting it.
   105	  process.stdout.write(
   106	    'SESSION-START SUMMARY — an instruction to you, not text to repeat. '
   107	    + 'Open your first reply of this session with exactly this line, and nothing before it:\n\n'
   108	    + `Claudinite loaded, ${facets.join(', ')}.\n`,
   109	  );
   110	} catch {
   111	  // fail soft — a broken summary must never block a session
   112	}
