test('the first fold after the upgrade rewrites the whole file, losing nothing', () => {
  // The answer to "is there a migration": no. The fold rewrites the file wholesale
  // every run from its decoded prior, so the version-1 file a repo is carrying is
  // converted by its next ordinary run — and the watermarks come across untouched, so
  // nothing is re-counted and no day is re-folded into a week that already has it.
  const v1 = {
    version: 1,
    foldedThrough: '2026-07-26',
    runsFoldedThrough: '2026-07-26T03:00:00Z',
    days: {
      '2026-07-26': {
        captures: 2, merges: 2, sessions: 1, userMessages: 9, userCommands: 1,
        skillLoads: { 'merge-to-main': 2 },
        checks: { work: { runs: 9, failures: 2, errors: 0, blocking: 3, advisory: 0, ciRuns: 0, ciFailures: 0 } },
        checkFindings: { 'task-lifecycle': { blocking: 3, advisory: 0 } },
        tasks: { 'tidy-repo/tidy-issues': { agent: 1, 'code-work': 0, skipped: 5, failed: 0, deferred: 0 } },
        taskExec: { 'tidy-repo/tidy-issues': { success: 1, failed: 0, 'task-gone': 0, invalid: 0 } },
      },
    },
    weeks: {
      '2026-W30': {
        days: 3, captures: 4, merges: 4, sessionDays: 3, userMessages: 40, userCommands: 1,
        skillLoads: { 'merge-to-main': 3 },
        checks: { work: { runs: 20, failures: 5, errors: 0, blocking: 8, advisory: 0, ciRuns: 0, ciFailures: 0 } },
        checkFindings: { 'task-lifecycle': { blocking: 8, advisory: 0 } },
        tasks: { 'tidy-repo/tidy-issues': { agent: 3, 'code-work': 0, skipped: 15, failed: 0, deferred: 0 } },
        taskExec: { 'tidy-repo/tidy-issues': { success: 3, failed: 0, 'task-gone': 0, invalid: 0 } },
      },
    },
  };
  // No new sources at all: the run that finds nothing to count still converts the file.
  const written = encodeUsage(foldUsage({ files: [], prior: decodeUsage(v1), today: '2026-07-27' }));
  const back = decodeUsage(written);
  assert.equal(written.version, USAGE_VERSION);
  assert.equal(written.foldedThrough, v1.foldedThrough, 'the day watermark does not move');
  assert.equal(written.runsFoldedThrough, v1.runsFoldedThrough, 'nor the run watermark');
  // Every frozen week row survives intact. `queue` is the one addition: a group map
  // always decodes present-and-empty, and an empty one carries nothing a reader cannot
  // derive — the row's own numbers are untouched.
===
  // This is what makes the format survive its own evolution: a file written when
  // `checks` was spelled in another order still reads as what it meant.
  const reversed = [...USAGE_FIELDS.checks].reverse();
  const row = { checks: { work: [1, 2, 3, 4, 5, 6, 7] } };
  const decoded = decodeRow(row, USAGE_FIELDS.day, { checks: reversed });
  assert.equal(decoded.checks.work[reversed[0]], 1);
  assert.equal(decoded.checks.work.runs, 7, 'the last slot is `runs` under that header');
});

test('a whole file round-trips, and version 1 decodes as itself', () => {
  const groups = { checks: {}, checkFindings: {}, tasks: {}, taskExec: {}, queue: {} };
  const named = {
    generated: '2026-07-27T04:00:00Z',
    foldedThrough: '2026-07-26',
    runsFoldedThrough: '2026-07-26T03:00:00Z',
    queueFoldedThrough: '2026-07-26T02:00:00Z',
    hours: { '2026-07-26T03': { scheduler: 2, executor: 1, agentic: 1, failed: 0, taskExec: {} } },
    days: { '2026-07-26': { captures: 2, merges: 2, sessions: 1, userMessages: 9, userCommands: 0, skillLoads: { s: 1 }, ...groups } },
    weeks: { '2026-W30': { days: 1, captures: 2, merges: 2, sessionDays: 1, userMessages: 9, userCommands: 0, skillLoads: { s: 1 }, ...groups } },
  };
  const file = encodeUsageFile(named);
  assert.equal(file.version, USAGE_VERSION);
  assert.equal(isTupleFormat(file), true);
  // An hour row carries only its own group; the decode fills the rest in empty, since
  // every consumer folds them key-wise.
  const back = decodeUsageFile(file);
  assert.deepEqual(back.hours['2026-07-26T03'], { ...named.hours['2026-07-26T03'], ...groups, skillLoads: {} });
  assert.deepEqual({ ...back, hours: named.hours }, named);

  const v1 = { version: 1, ...named };
  assert.equal(isTupleFormat(v1), false);
  assert.deepEqual(decodeUsageFile(v1).weeks, named.weeks, 'the original shape passes through untouched');
  assert.deepEqual(decodeUsageFile(v1).hours, {}, 'a file that predates the hour tier starts it empty');
});

test('the stamp is the one line the unchanged-compare ignores', () => {
  // The whole reason the file can carry a freshness stamp at all: it moves every run
  // by construction, so a compare that read it would open a PR an hour on a repo where
