1	// The usage fold's THIRD source: what each scheduled occurrence actually came to.
2	//
3	// The slot scheduler used to print that per due task into its own Actions log, and the
4	// fold counted those lines. That writer retired with the slot scheduler (#974) and the
5	// queue does not print an equivalent — because it does not need to. Every occurrence
6	// is a work ITEM, and when it converges it closes wearing an `outcome:*` label. The
7	// record is better than the log line was (it survives Actions retention, it is
8	// clickable, and it carries the task on its own title) and it is a different read,
9	// which is what #994 asked for. This module is that read.
10	//
11	// APPEND-ONCE past `queueFoldedThrough`, for the same reason the run listing is
12	// forward-only: this is a paged REST resource where the capture files are local git.
13	// It is safe to append rather than recompute because a CLOSED item is settled — the
14	// outcome label is written at convergence and nothing later moves it — so an item is
15	// counted on the one fold that first sees it closed and never again.
16	//
17	// The boundary is `closed_at`, not `updated_at`: the listing is asked for everything
18	// touched since the mark (a comment on an old item counts as a touch), and only items
19	// that closed past the mark are counted. Closing happens in real time, so the mark is
20	// monotone and the filter is exactly-once.
21	//
22	// FAIL-SOFT, like every other source here: an unreadable listing costs the queue rows
23	// this run and leaves the mark where it was.
24	
25	// One definition of what a work item is, shared with the queue's own reader — a filed
26	// `[claudinite-work]` issue OR an adopted marked issue, which keeps the person's title.
27	import { isQueueItem } from '../../../claudinite-tasks/queue/read.mjs';
28	import {
29	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, outcomeOf,
30	  PARK_PREFIX, PARK_KINDS, NEEDS_HUMAN,
31	} from '../../../claudinite-tasks/queue/work-item.mjs';
32	
33	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
34	
35	// How far back the FIRST read looks with no mark yet — the day tier's own width, so
36	// one fold populates the whole window rather than starting it empty.
37	export const FIRST_READ_LOOKBACK_DAYS = 30;
38	
39	export const lookbackFrom = (nowIso, days = FIRST_READ_LOOKBACK_DAYS) =>
40	  new Date(new Date(nowIso).getTime() - days * 86400000).toISOString();
41	
42	export function makeReader({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
43	  const headers = {
44	    accept: 'application/vnd.github+json',
45	    'x-github-api-version': '2022-11-28',
46	    'user-agent': 'claudinite-usage-fold',
47	    ...(token ? { authorization: `Bearer ${token}` } : {}),
48	  };
49	  return {
50	    async json(path) {
51	      const res = await fetchImpl(`${api}${path}`, { headers });
52	      if (res.status !== 200) return null;
53	      try { return await res.json(); } catch { return null; }
54	    },
55	  };
56	}
57	
58	// The task an item belongs to. A filed item says so in its title; an ADOPTED marked
59	// issue keeps the person's own title and says so in the machine block its body carries
60	// — the same two-step the dashboard's own reader makes, so a request-shaped run is not
61	// silently counted as belonging to no task.
62	export function taskOf(issue) {
63	  const fromTitle = parseWorkItemTitle(issue?.title);
64	  if (fromTitle) return { pack: fromTitle.pack, task: fromTitle.task };
65	  const fromBody = taskIdFromPath(parseWorkItemBody(issue?.body).taskPath);
66	  return fromBody ? { pack: fromBody.pack, task: fromBody.task } : null;
67	}
