69	// --- the parks an item collected -------------------------------------------------
70	// A park is a label an item WORE, so the only record of one is the label event that
71	// applied it — the item's final labels say where it ended, never where it stopped on
72	// the way. So each closed item's event listing is read once, on the fold that first
73	// sees it closed, under the queue's own watermark.
74	//
75	// The kinds are decoded exactly as `parkOf` decodes them for a live item: today's
76	// single `task:status:needs-human-<kind>`, the two-label era's `task:needs-human-<kind>`
77	// sub-label, and a kind no engine here knows reading as `failure` — the conservative
78	// lane, so a park whose word this code predates is never dropped.
79	const LEGACY_PARK_RE = /^task:needs-human-(.+)$/;
80	
81	export function parkKindOf(label) {
82	  const name = String(label ?? '');
83	  if (name === NEEDS_HUMAN) return 'failure';
84	  const kind = name.startsWith(PARK_PREFIX)
85	    ? name.slice(PARK_PREFIX.length)
86	    : LEGACY_PARK_RE.exec(name)?.[1] ?? null;
87	  if (kind === null) return null;
88	  return PARK_KINDS.includes(kind) ? kind : 'failure';
89	}
90	
91	// The park kinds one item collected, DEDUPED: an item bounced between a person and the
92	// machine twice was parked for that kind once as far as "how often did this task need a
93	// human" is concerned. `null` — never `[]` — when the listing could not be read, so an
94	// unknown park count stays distinguishable from a clean run.
95	export async function readParks({ reader, repo, number }) {
96	  let events = null;
