98	  if (!Array.isArray(events)) return null;
99	  const kinds = new Set();
100	  for (const event of events) {
101	    if (event?.event !== 'labeled') continue;
102	    const kind = parkKindOf(event?.label?.name);
103	    if (kind) kinds.add(kind);
104	  }
105	  return [...kinds];
106	}
107	
108	// One closed item → a record, or null when it is not this fold's business.
109	export function recordFor(issue, since) {
110	  if (!isQueueItem(issue)) return null;
111	  const closedAt = issue?.closed_at ?? null;
112	  if (!closedAt) return null;
113	  if (since && closedAt <= since) return null;
114	  const task = taskOf(issue);
115	  if (!task) return null;
116	  return {
117	    date: closedAt.slice(0, 10), closedAt, ...task, outcome: outcomeOf(issue) ?? 'none',
118	    number: issue?.number ?? null,
119	    // Filled by the caller from the item's own event listing; `null` until then, and
120	    // `null` still if that listing could not be read.
121	    parks: null,
122	  };
123	}
124	
125	// The whole read: `{ records, watermark, error? }`.
126	export async function readQueueOutcomes({ reader, repo, since, now, maxPages = 5 }) {
127	  const from = since || lookbackFrom(now);
128	  const records = [];
129	  try {
130	    for (let page = 1; page <= maxPages; page += 1) {
131	      const path = `/repos/${repo}/issues?state=closed&sort=updated&direction=desc`
132	        + `&since=${encodeURIComponent(from)}&per_page=100&page=${page}`;
133	      const batch = await reader.json(path);
134	      if (!Array.isArray(batch) || batch.length === 0) break;
135	      for (const issue of batch) {
136	        if (issue?.pull_request) continue;         // the issues endpoint answers with both
137	        const rec = recordFor(issue, since);
138	        if (rec) records.push(rec);
139	      }
140	      if (batch.length < 100) break;
141	    }
142	  } catch {
143	    return { records: [], watermark: since, error: 'the closed work items could not be listed' };
144	  }
145	  // One listing per item, and only for the items this fold is seeing close for the
146	  // first time — the watermark above is what bounds the cost. An item whose listing
147	  // fails keeps `parks: null` and its outcome row regardless.
148	  for (const rec of records) {
149	    if (rec.number === null) continue;
150	    rec.parks = await readParks({ reader, repo, number: rec.number });
151	  }
152	  const newest = records.map((r) => r.closedAt).sort().pop() ?? null;
153	  return { records, watermark: newest ?? since ?? null };
154	}

