57	const git = (root, args) => execFileSync('git', ['-C', root, ...args], {
58	  encoding: 'utf8',
59	  // A capture blob easily tops the default 1 MiB buffer — a long session's log then
60	  // dies mid-read and the day it lands in silently under-counts.
61	  maxBuffer: 256 * 1024 * 1024,
