  const current = windowOf(dayKey(now - (windowDays - 1) * DAY_MS), dayKey(now + DAY_MS));
  const previous = windowOf(dayKey(now - (2 * windowDays - 1) * DAY_MS), dayKey(now - (windowDays - 1) * DAY_MS));

