import { chromium } from 'playwright';

const arg = (name, fallback = null) => {
  const i = process.argv.indexOf(`--${name}`);
  return i > -1 ? process.argv[i + 1] : fallback;
};

const url = arg('url');
const out = arg('out');
const width = Number(arg('width', '1280'));
const theme = arg('theme', 'light');
const measure = arg('measure', null);

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width, height: 1400 }, deviceScaleFactor: 2 });
page.on('console', (m) => { if (m.type() === 'error') console.error('page error:', m.text()); });
page.on('pageerror', (e) => console.error('page exception:', e.message));

await page.addInitScript(({ fixture }) => {
  window.__fixture = fixture;
  const json = (body, headers = {}) => ({
    ok: true, status: 200,
    headers: { get: (k) => ({ 'x-ratelimit-remaining': '4300', 'x-ratelimit-limit': '5000', ...headers })[k.toLowerCase()] ?? null },
    json: async () => body,
    text: async () => (typeof body === 'string' ? body : JSON.stringify(body)),
  });
  const real = window.fetch;
  window.fetch = async (input, init) => {
    const href = String(input?.url ?? input);
    if (!href.includes('api.github.com')) return real(input, init);
    const f = window.__fixture;
    for (const [pattern, body] of f.routes) {
      if (new RegExp(pattern).test(href)) return json(body);
    }
    return json([]);
  };
  window.localStorage.clear();
}, { fixture: JSON.parse(process.env.FIXTURE ?? '{"routes":[]}') });

await page.emulateMedia({ colorScheme: theme });
await page.goto(url, { waitUntil: 'networkidle' });
await page.waitForTimeout(1200);

if (measure) {
  const box = await page.locator(measure).first().boundingBox();
  console.log(JSON.stringify({ selector: measure, top: box ? Math.round(box.y) : null }));
}
await page.screenshot({ path: out, fullPage: false });
await browser.close();
